      "duration": 0.5
    },
    {
      "keystrokes": "ls -la encrypted_data/\n",
      "duration": 0.1
    },
    {
      "keystrokes": "echo '--- originals ---'; cat data/sample1.txt data/sample2.txt; echo; echo '--- encrypted ---'; cat encrypted_data/sample1.txt encrypted_data/sample2.txt; echo\n",
      "duration": 0.2
    }
  ]
}

